svg.script:
(async () => {
  const o = document.getElementById("refract-status");
  const a = document.getElementById("refract-frame");
  const l = e => {
    o.textContent = "Unable to start Refract: " + (e && e.message ? e.message : String(e));
    o.setAttribute("data-error", "");
  };

  // iOS/iPadOS: SW can't control iframes — redirect top window directly to app scope
  const isIOS = /iP(hone|ad|od)/.test(navigator.userAgent) ||
    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);

  if (isIOS) {
    const scope = new URL("./", location.href).href;
    location.replace(scope);
    return;
  }

  try {
    if (new URL(location.href).searchParams.has("refract-bootstrap-error"))
      throw new Error("bootstrap error test");
    if (!("serviceWorker" in navigator))
      throw new Error("service workers are unavailable");

    const e = new URL("./", location.href).href;
    const i = await navigator.serviceWorker.register(
      new URL("./GQC2eo6.js", location.href), { scope: e }
    );

    let r = i.active || i.waiting || i.installing;
    if (!r) throw new Error("service worker is unavailable");

    if (r.state !== "activated") await new Promise((s, c) => {
      const t = () => {
        if (r.state === "activated") { r.removeEventListener("statechange", t); s(); }
        else if (r.state === "redundant") { r.removeEventListener("statechange", t); c(new Error("service worker activation failed")); }
      };
      r.addEventListener("statechange", t); t();
    });

    if (!navigator.serviceWorker.controller) await new Promise((s, c) => {
      const t = setTimeout(() => {
        navigator.serviceWorker.removeEventListener("controllerchange", n);
        c(new Error("service worker control timed out"));
      }, 5000);
      const n = () => {
        if (navigator.serviceWorker.controller) {
          clearTimeout(t);
          navigator.serviceWorker.removeEventListener("controllerchange", n);
          s();
        }
      };
      navigator.serviceWorker.addEventListener("controllerchange", n); n();
    });

    if (window.parent !== window && location.hash === "#refract-launcher") {
      parent.postMessage("refract-sw-ready", "*");
      return;
    }

    a.addEventListener("load", () => { o.hidden = true; a.style.display = "block"; }, { once: true });
    a.addEventListener("error", () => l(new Error("application frame failed to load")), { once: true });
    a.setAttribute("src", e);

  } catch (e) { l(e); }
})();
